import js from "@eslint/js"
import { defineConfig, globalIgnores } from "eslint/config"
import reactHooks from "eslint-plugin-react-hooks"
import reactRefresh from "eslint-plugin-react-refresh"
import globals from "globals"
import tseslint from "typescript-eslint"

// Generated by the shadcn CLI and kept identical to upstream; linted with the
// template defaults only. See docs/DEV_PLAN.md section 7.2 for the UI rules.
const VENDORED = ["src/components/ui/**", "src/hooks/use-mobile.ts"]

const OTHER_UI_LIBRARIES = [
  "@mui/*",
  "@material-ui/*",
  "antd",
  "@ant-design/*",
  "@arco-design/*",
  "tdesign-react",
  "@chakra-ui/*",
  "@mantine/*",
  "@headlessui/*",
  "@heroui/*",
  "@nextui-org/*",
  "react-bootstrap",
  "primereact",
  "semantic-ui-react",
  "@radix-ui/*",
  "radix-ui",
  "react-aria-components",
]

const COLOR_LITERAL = String.raw`/#[0-9a-fA-F]{3,8}\b|\b(?:rgba?|hsla?|oklch|oklab|lab|lch|hwb|color)\(/`
const PALETTE_CLASS = String.raw`/\b(?:bg|text|border|ring|fill|stroke|from|via|to|outline|decoration|shadow|accent|caret|divide|placeholder)-(?:slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose|black|white)(?:-\d{2,3})?\b/`
const TOKEN_MESSAGE =
  "Use theme tokens (bg-primary, text-muted-foreground, border-border, ...) instead of literal or palette colors."

function classStringRules(regex) {
  return [
    `JSXAttribute[name.name='className'] Literal[value=${regex}]`,
    `JSXAttribute[name.name='className'] TemplateElement[value.raw=${regex}]`,
    `CallExpression[callee.name=/^(cn|cva)$/] Literal[value=${regex}]`,
    `CallExpression[callee.name=/^(cn|cva)$/] TemplateElement[value.raw=${regex}]`,
  ].map((selector) => ({ selector, message: TOKEN_MESSAGE }))
}

export default defineConfig([
  globalIgnores([
    "dist",
    "coverage",
    "playwright-report",
    "test-results",
    "src/lib/api/schema.d.ts",
  ]),
  {
    files: ["**/*.{ts,tsx}"],
    ignores: VENDORED,
    extends: [
      js.configs.recommended,
      tseslint.configs.strictTypeChecked,
      tseslint.configs.stylisticTypeChecked,
      reactHooks.configs.flat.recommended,
      reactRefresh.configs.vite,
    ],
    languageOptions: {
      globals: globals.browser,
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
    rules: {
      "react-refresh/only-export-components": "off",
      "@typescript-eslint/restrict-template-expressions": [
        "error",
        { allowNumber: true },
      ],
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              group: OTHER_UI_LIBRARIES,
              message:
                "Use shadcn/ui components from @/components/ui; add missing ones with the shadcn CLI.",
            },
            {
              group: ["@base-ui/react", "@base-ui/react/*"],
              message:
                "Base UI primitives belong in src/components/ui; compose the shadcn components instead.",
            },
          ],
        },
      ],
      "no-restricted-syntax": [
        "error",
        ...classStringRules(COLOR_LITERAL),
        ...classStringRules(PALETTE_CLASS),
        {
          selector: `JSXAttribute[name.name='style'] Property > Literal[value=${COLOR_LITERAL}]`,
          message: TOKEN_MESSAGE,
        },
      ],
    },
  },
  {
    files: VENDORED,
    extends: [
      js.configs.recommended,
      tseslint.configs.recommended,
      reactHooks.configs.flat.recommended,
    ],
    languageOptions: { globals: globals.browser },
    rules: {
      // Upstream use-mobile.ts syncs its initial value inside an effect.
      "react-hooks/set-state-in-effect": "off",
    },
  },
  {
    files: ["e2e/**/*.ts", "*.config.ts"],
    languageOptions: { globals: globals.node },
  },
  {
    files: ["**/*.{js,mjs}"],
    extends: [js.configs.recommended],
    languageOptions: { globals: { ...globals.browser, ...globals.node } },
  },
])
